#import "SLHomeViewController.h"
#import "SLAPI.h"
#import "SLStore.h"
#import "SLTitleViewController.h"
#import "SLReaderViewController.h"
#import "SLTheme.h"
#import <stdlib.h>
#import "SLImageLoader.h"
@implementation SLHomeViewController
- (void)viewDidLoad{[super viewDidLoad];self.title=@"Главная";_recent=[[NSMutableArray alloc]init];_shelves=[[NSMutableArray alloc]init];self.tableView.rowHeight=66;self.tableView.backgroundColor=[SLTheme backgroundColor];self.navigationItem.rightBarButtonItem=[[[UIBarButtonItem alloc]initWithTitle:@"Обновить" style:UIBarButtonItemStylePlain target:self action:@selector(load)]autorelease];[self load];}
- (void)viewWillAppear:(BOOL)animated{[super viewWillAppear:animated];self.tableView.backgroundColor=[SLTheme backgroundColor];[_recent setArray:[SLStore array:@"SLHistory"]];[self.tableView reloadData];}
- (void)load{[_recent setArray:[SLStore array:@"SLHistory"]];[_shelves removeAllObjects];[self.tableView reloadData];[[SLAPI shared]catalogPage:(NSInteger)(arc4random_uniform(20)+1) genreID:nil completion:^(id root,NSError *err){NSArray *rows=[root isKindOfClass:[NSDictionary class]]?[root objectForKey:@"data"]:nil;if([rows isKindOfClass:[NSArray class]])[_shelves addObject:[NSDictionary dictionaryWithObjectsAndKeys:@"Случайные находки",@"name",rows,@"rows",nil]];[self.tableView reloadData];}];[[SLAPI shared]genres:^(id root,NSError *err){NSDictionary *data=[root objectForKey:@"data"];NSArray *genres=[data objectForKey:@"genres"];if(![genres isKindOfClass:[NSArray class]])return;NSMutableArray *valid=[NSMutableArray array];for(NSDictionary *g in genres)if([g objectForKey:@"id"]&&[[g objectForKey:@"name"]isKindOfClass:[NSString class]])[valid addObject:g];for(NSUInteger i=0;i<4&&[valid count];i++){NSUInteger index=arc4random_uniform((u_int32_t)[valid count]);NSDictionary *genre=[valid objectAtIndex:index];[valid removeObjectAtIndex:index];NSInteger page=(NSInteger)(arc4random_uniform(3)+1);[[SLAPI shared]catalogPage:page genreID:[genre objectForKey:@"id"] completion:^(id result,NSError *e){NSArray *titles=[[result objectForKey:@"data"]isKindOfClass:[NSArray class]]?[result objectForKey:@"data"]:nil;if([titles count]){[_shelves addObject:[NSDictionary dictionaryWithObjectsAndKeys:[genre objectForKey:@"name"],@"name",titles,@"rows",nil]];[self.tableView reloadData];}}];}}];}
- (NSInteger)numberOfSectionsInTableView:(UITableView *)t{return 1+[_shelves count];}
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s{if(s==0)return [_recent count];return [[[_shelves objectAtIndex:s-1]objectForKey:@"rows"]count];}
- (NSString *)tableView:(UITableView *)t titleForHeaderInSection:(NSInteger)s{return s==0?@"Продолжить чтение": [[_shelves objectAtIndex:s-1]objectForKey:@"name"];}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)p{static NSString *i=@"HomeTitle";UITableViewCell *c=[t dequeueReusableCellWithIdentifier:i];if(!c)c=[[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:i]autorelease];NSDictionary *d=p.section==0?[_recent objectAtIndex:p.row]:[[[_shelves objectAtIndex:p.section-1]objectForKey:@"rows"]objectAtIndex:p.row];c.textLabel.text=[d objectForKey:@"rus_name"]?:[d objectForKey:@"name"]?:[d objectForKey:@"slug_url"]?:@"Манга";NSDictionary *ch=[d objectForKey:@"_lastChapter"];c.detailTextLabel.text=ch?[NSString stringWithFormat:@"Продолжить · Том %@, глава %@",[ch objectForKey:@"volume"]?:@"?",[ch objectForKey:@"number"]?:@"?"]:[d objectForKey:@"eng_name"];NSDictionary *cover=[d objectForKey:@"cover"];NSString *coverURL=[cover isKindOfClass:[NSDictionary class]]?([cover objectForKey:@"thumbnail"]?:[cover objectForKey:@"default"]):nil;c.imageView.image=nil;c.imageView.accessibilityIdentifier=coverURL;if([coverURL length])[[SLImageLoader shared]load:coverURL site:[[d objectForKey:@"site"]integerValue] completion:^(UIImage *image){if([c.imageView.accessibilityIdentifier isEqualToString:coverURL]){c.imageView.image=image;[c setNeedsLayout];}}];c.textLabel.textColor=[SLTheme textColor];c.detailTextLabel.textColor=[SLTheme textColor];c.backgroundColor=[SLTheme backgroundColor];c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return c;}
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)p{[t deselectRowAtIndexPath:p animated:YES];NSDictionary *item=p.section==0?[_recent objectAtIndex:p.row]:[[[_shelves objectAtIndex:p.section-1]objectForKey:@"rows"]objectAtIndex:p.row];if(p.section==0&&[item objectForKey:@"_lastChapter"]){NSString *slug=[item objectForKey:@"slug_url"]?:[[item objectForKey:@"id"]description];SLReaderViewController *reader=[[[SLReaderViewController alloc]initWithSlug:slug chapter:[item objectForKey:@"_lastChapter"] titleInfo:item]autorelease];[self.navigationController pushViewController:reader animated:YES];}else{SLTitleViewController *v=[[[SLTitleViewController alloc]initWithTitle:item]autorelease];[self.navigationController pushViewController:v animated:YES];}}
- (void)dealloc{[_recent release];[_shelves release];[super dealloc];}
@end
